<?php
namespace App\Http\Controllers;use App\Models\Lead;use Illuminate\Http\Request;
final class LeadController extends Controller {public function index(Request $r){$q=Lead::query();if($r->filled('q')){$s=(string)$r->input('q');$q->where(fn($x)=>$x->where('company','like',"%{$s}%")->orWhere('email','like',"%{$s}%")->orWhere('first_name','like',"%{$s}%")->orWhere('last_name','like',"%{$s}%"));}if($r->filled('status'))$q->where('status',$r->input('status'));return view('leads.index',['leads'=>$q->orderByDesc('score')->latest('updated_at')->paginate(25)->withQueryString()]);}public function create(){return view('leads.form',['lead'=>new Lead]);}public function store(Request $r){$lead=Lead::create($this->data($r));return redirect()->route('leads.show',$lead)->with('status',__('ui.saved'));}public function show(Lead $lead){return view('leads.show',['lead'=>$lead,'activities'=>$lead->activities()->latest('occurred_at')->paginate(15)]);}public function edit(Lead $lead){return view('leads.form',['lead'=>$lead]);}public function update(Request $r,Lead $lead){$lead->update($this->data($r));return redirect()->route('leads.show',$lead)->with('status',__('ui.saved'));}public function destroy(Lead $lead){$lead->delete();return redirect()->route('leads.index')->with('status',__('ui.deleted'));}public function export(){return response()->streamDownload(function(){ $out=fopen('php://output','w');fputcsv($out,['id','first_name','last_name','email','phone','title','company','website','linkedin_url','city','country','status','score','source','source_url']);Lead::orderBy('id')->chunk(500,function($leads)use($out){foreach($leads as $lead)fputcsv($out,[$lead->id,$lead->first_name,$lead->last_name,$lead->email,$lead->phone,$lead->title,$lead->company,$lead->website,$lead->linkedin_url,$lead->city,$lead->country,$lead->status,$lead->score,$lead->source,$lead->source_url]);});fclose($out);},'enverif-leads-'.now()->format('Y-m-d').'.csv',['Content-Type'=>'text/csv']);}private function data(Request $r):array{return $r->validate(['first_name'=>'nullable|max:100','last_name'=>'nullable|max:100','email'=>'nullable|email|max:255','phone'=>'nullable|max:80','title'=>'nullable|max:150','company'=>'nullable|max:180','website'=>'nullable|url|max:500','linkedin_url'=>'nullable|url|max:500','city'=>'nullable|max:120','country'=>'nullable|max:120','status'=>'required|in:new,researching,qualified,contacted,replied,meeting,won,lost,disqualified','score'=>'required|integer|min:0|max:100','source'=>'nullable|max:80','source_url'=>'nullable|url|max:1000','research_summary'=>'nullable|string|max:30000']);}}
